def copy_structures_to_admin(apps, schema_editor):
    Utilisateur = apps.get_model('core', 'Utilisateur')
    for user in Utilisateur.objects.all():
        user.structures_admin.set(user.structures.all())


def affecter_permission_avances(apps, schema_editor):
    Permission = apps.get_model('auth', 'Permission')
    Utilisateur = apps.get_model('core', 'Utilisateur')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    ct = ContentType.objects.get_for_model(Utilisateur)
    perm, created = Permission.objects.get_or_create(
        codename='avances_regul',
        content_type=ct,
        defaults={'name': 'Comptabilité | Régulariser les avances'}
    )
    for user in Utilisateur.objects.filter(is_active=True):
        user.user_permissions.add(perm)


